// ============================================================
// ZCare AI — context preparation
// ============================================================
// Turns retrieved records into:
//   * contextText — compact, dated, sectioned text for the model
//   * facts       — the same facts for the "What your records show" card
//   * sources     — the records that were actually considered
//   * missing / omitted / caveats — never silently dropped
// Values, units, reference ranges and dates are copied verbatim from
// the records; nothing here is generated by the model.

import type {
  BuiltContext,
  ContextBudget,
  FactItem,
  FactSection,
  FactTone,
  HealthTopic,
  PatientRecords,
  QuestionAnalysis,
  RankedChunk,
  RecordCategory,
  SafetyAssessment,
  SourceRef,
} from '../../types/ai.types.ts';
import type { Allergy, Consultation, Medication } from '../../types/index.ts';
import type { LabResult } from '../../types/medicalExtraction.ts';
import { relatedLabFamiliesForSymptoms, normalizeText } from './intent.service.ts';
import {
  RELATED_ALLERGY_CLASSES,
  allergyClasses,
  canonicalDrugNames,
  drugClassesFor,
  findLabFamily,
  labFamiliesForTest,
} from './medical-lexicon.ts';
import { sanitizeUntrustedText } from './safety.service.ts';

// ------------------------------------------------------------
// Small helpers
// ------------------------------------------------------------
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

export function isoDay(value: string | null | undefined): string | null {
  if (!value) return null;
  const m = String(value).match(/^(\d{4})-(\d{2})-(\d{2})/);
  return m ? `${m[1]}-${m[2]}-${m[3]}` : null;
}

type DateFmt = (iso: string | null | undefined) => string;
const fmtIso: DateFmt = v => isoDay(v) ?? 'date not recorded';
const fmtHuman: DateFmt = v => {
  const d = isoDay(v);
  if (!d) return 'date not recorded';
  const [y, m, day] = d.split('-');
  return `${day} ${MONTHS[Number(m) - 1]} ${y}`;
};

function daysBetween(fromIso: string, to: Date): number {
  const from = new Date(`${fromIso}T00:00:00Z`).getTime();
  const toDay = Date.UTC(to.getUTCFullYear(), to.getUTCMonth(), to.getUTCDate());
  return Math.round((toDay - from) / 86_400_000);
}

export function ageOn(dob: string | null | undefined, now: Date): number | null {
  const d = isoDay(dob);
  if (!d) return null;
  const [y, m, day] = d.split('-').map(Number);
  let age = now.getUTCFullYear() - y;
  if (now.getUTCMonth() + 1 < m || (now.getUTCMonth() + 1 === m && now.getUTCDate() < day)) age--;
  return age >= 0 && age < 130 ? age : null;
}

const clean = (text: string | null | undefined, max: number) => sanitizeUntrustedText(text, max).text;

/** Parses "14.2", "7,800" or "1,23,000" -> number. Qualified values ("<0.5", "2.45 lakh") return null. */
export function parseNumeric(value: string | null | undefined): number | null {
  if (value === null || value === undefined) return null;
  const v = String(value).trim();
  if (!/^-?\d{1,3}(,\d{2,3})*(\.\d+)?$|^-?\d+(\.\d+)?$/.test(v)) return null;
  const n = Number(v.replace(/,/g, ''));
  return Number.isFinite(n) ? n : null;
}

export interface ParsedRange {
  low: number | null;
  high: number | null;
}

/** Parses "4.0 - 5.6", "70-100", "< 200", ">= 40", "Up to 40". */
export function parseRange(range: string | null | undefined): ParsedRange | null {
  if (!range) return null;
  const r = String(range).replace(/[–—]/g, '-').replace(/,/g, '').trim().toLowerCase();
  let m = r.match(/^(-?\d+(?:\.\d+)?)\s*(?:-|to)\s*(-?\d+(?:\.\d+)?)/);
  if (m) return { low: Number(m[1]), high: Number(m[2]) };
  m = r.match(/^(?:<|<=|≤|up to|upto|less than|below)\s*(-?\d+(?:\.\d+)?)/);
  if (m) return { low: null, high: Number(m[1]) };
  m = r.match(/^(?:>|>=|≥|more than|above|greater than)\s*(-?\d+(?:\.\d+)?)/);
  if (m) return { low: Number(m[1]), high: null };
  return null;
}

type LabFlag = 'normal' | 'high' | 'low' | 'critical' | 'unknown';

/** Range position calculated from the numbers (null when not computable). */
export function computedLabFlag(lab: Pick<LabResult, 'result_value' | 'reference_range'>): 'normal' | 'high' | 'low' | null {
  const value = parseNumeric(lab.result_value);
  const range = parseRange(lab.reference_range);
  if (value === null || !range) return null;
  if (range.high !== null && value > range.high) return 'high';
  if (range.low !== null && value < range.low) return 'low';
  return 'normal';
}

export function effectiveLabFlag(lab: LabResult): { flag: LabFlag; conflict: boolean; computed: 'normal' | 'high' | 'low' | null } {
  const computed = computedLabFlag(lab);
  const recorded = (lab.result_status ?? 'unknown') as LabFlag;
  if (recorded === 'critical') return { flag: 'critical', conflict: false, computed };
  if (recorded === 'unknown' || !recorded) return { flag: computed ?? 'unknown', conflict: false, computed };
  const conflict = computed !== null && computed !== recorded;
  return { flag: recorded, conflict, computed };
}

export function normalizeTestName(name: string): string {
  return normalizeText(name).replace(/\([^)]*\)/g, ' ').replace(/[^a-z0-9]+/g, ' ').trim();
}

function distanceFromRange(value: number, range: ParsedRange): number {
  if (range.high !== null && value > range.high) return value - range.high;
  if (range.low !== null && value < range.low) return range.low - value;
  return 0;
}

function round(n: number): string {
  return String(Math.round(n * 100) / 100);
}

